import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
  interpolateColors,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type ClientContractAnimationProps = Record<string, any>;

const ClientContractAnimation: React.FC<ClientContractAnimationProps> = ({
  backgroundColor = "#ffffff",
  transparentBackground = false,
  durationInSeconds = 6,
  titleText = "Client Contract",
  buttonText = "Finish Signing",
  signatureText = "Client Signature",
  verifiedText = "Signature verified by Malloy Studio",
  primaryColor = "#a3c5ff",
  completedButtonColor = "#0055ff",
  titleColor = "#888888",
  skeletonColor = "#c0c0c0",
  boxColor = "#f2f2f2",
  verifiedBadgeColor = "#0bc159",
  verifiedTextColor = "#555555",
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter", "Dancing Script"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Layout calculations updated to maintain safe distance from all edges
  const paddingX = width * 0.12;
  const paddingY = height * 0.08;
  const contentWidth = width * 0.6;
  const skeletonHeight = height * 0.015; // Slightly reduced to ensure vertical fit
  const lineGap = height * 0.015;
  const paraGap = height * 0.025;

  // Title Animation
  const titleOpacity = interpolate(frame, [0, 15], [0, 1], {
    extrapolateRight: "clamp",
  });
  const titleY = interpolate(frame, [0, 15], [30, 0], {
    extrapolateRight: "clamp",
  });

  // Data structure for paragraphs (representing relative width of each line)
  const paragraphs = [
    [1, 1, 1, 0.45],
    [1, 1, 0.85],
    [1, 1, 1, 1, 0.25],
  ];

  // Signature Box Animation - Timing shifted earlier
  const sigBoxScale = spring({
    frame: frame - 35,
    fps,
    config: { damping: 14, stiffness: 100 },
  });

  // Button Entrance Animation
  const buttonEntranceScale = spring({
    frame: frame - 45,
    fps,
    config: { damping: 12 },
  });
  
  // Signature Drawing Animation - Timing shifted earlier
  const signatureDrawProgress = interpolate(frame, [65, 95], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // Button Color Transition finishes at frame 110
  const buttonBgColor = interpolateColors(
    frame,
    [95, 110],
    [primaryColor, completedButtonColor]
  );

  // --- NEW TIMING LOGIC ---
  const clickStartFrame = 115;
  const clickEndFrame = 125;
  const loadingStartFrame = 125;
  const loadingDurationFrames = Math.max(1, Math.round(fps * 0.25)); // 0.25 seconds
  const loadingEndFrame = loadingStartFrame + loadingDurationFrames;
  const badgeStartFrame = loadingEndFrame;

  // Button Click Scale (squish and pop)
  const buttonClickScale = interpolate(
    frame,
    [clickStartFrame, clickStartFrame + 5, clickEndFrame],
    [1, 0.92, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const finalButtonScale = buttonEntranceScale * buttonClickScale;
  
  // Button disappears immediately at clickEndFrame
  const buttonOpacity = frame >= clickEndFrame ? 0 : (buttonEntranceScale > 0 ? 1 : 0);

  // Loading Animation (fades in slightly overlapping, fades out quickly)
  const loadingOpacity = interpolate(
    frame,
    [loadingStartFrame, loadingStartFrame + 2, loadingEndFrame - 2, loadingEndFrame],
    [0, 1, 1, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  // Quick spinning rotation
  const loadingRotation = interpolate(
    frame,
    [loadingStartFrame, loadingEndFrame],
    [0, 360],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Badge pops in after loading
  const badgeScale = spring({
    frame: frame - badgeStartFrame,
    fps,
    config: { damping: 12, stiffness: 120 },
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter, sans-serif",
        display: "flex",
        flexDirection: "column",
        justifyContent: "center", // Ensures exact vertical centering within padding
        padding: `${paddingY}px ${paddingX}px`, // Establishes safe zone off all canvas edges
        boxSizing: "border-box",
        transition: "none",
      }}
    >
      {/* Title */}
      <div
        style={{
          fontSize: width * 0.045,
          fontWeight: 500,
          color: titleColor,
          opacity: titleOpacity,
          transform: `translateY(${titleY}px)`,
          marginBottom: height * 0.03, // Tighter to maintain vertical safe zones
          transition: "none",
        }}
      >
        {titleText}
      </div>

      {/* Skeletons */}
      <div style={{ width: contentWidth, display: "flex", flexDirection: "column", transition: "none" }}>
        {paragraphs.map((para, pIndex) => (
          <div
            key={`para-${pIndex}`}
            style={{
              display: "flex",
              flexDirection: "column",
              gap: lineGap,
              marginBottom: paraGap,
              transition: "none",
            }}
          >
            {para.map((lineWidth, lIndex) => {
              const lineStartFrame = 15;
              const widthProgress = spring({
                frame: frame - lineStartFrame,
                fps,
                config: { damping: 18, stiffness: 120 },
              });

              return (
                <div
                  key={`line-${pIndex}-${lIndex}`}
                  style={{
                    height: skeletonHeight,
                    backgroundColor: skeletonColor,
                    borderRadius: skeletonHeight / 2,
                    width: `${lineWidth * widthProgress * 100}%`,
                    transformOrigin: "left center",
                    transition: "none",
                  }}
                />
              );
            })}
          </div>
        ))}
      </div>

      {/* Signature Area */}
      <div
        style={{
          width: contentWidth * 0.4,
          height: height * 0.15, // Reduced slightly to respect boundaries
          backgroundColor: boxColor,
          borderRadius: 16,
          marginTop: height * 0.02,
          display: "flex",
          alignItems: "center",
          padding: "0 40px",
          transform: `scale(${sigBoxScale})`,
          opacity: sigBoxScale > 0 ? 1 : 0,
          position: "relative",
          overflow: "hidden",
          transition: "none",
        }}
      >
        {/* Animated Signature Text */}
        <div
          style={{
            position: "absolute",
            left: "80px",
            top: "50%",
            transform: "translateY(-50%)",
            fontFamily: "'Dancing Script', cursive",
            fontSize: width * 0.028,
            color: "#000000",
            clipPath: `inset(0 ${100 - signatureDrawProgress * 100}% 0 0)`,
            whiteSpace: "nowrap",
            transition: "none",
          }}
        >
          {signatureText}
        </div>

        {/* Static Pen Icon */}
        <div
          style={{
            position: "absolute",
            left: "40px",
            top: "50%",
            transform: "translateY(-50%)",
            transition: "none",
            zIndex: 10,
          }}
        >
          <svg width="20" height="34" viewBox="0 0 20 34">
            <path
              d="M 2 0 L 18 0 L 18 20 L 10 32 L 2 20 Z"
              fill="#3a3a3a"
            />
          </svg>
        </div>
      </div>

      {/* Bottom Action Area (Relative wrapper to prevent layout jumps) */}
      <div style={{ marginTop: height * 0.03, position: "relative", height: 80 }}>
        
        {/* The Original Button */}
        <div
          style={{
            position: "absolute",
            backgroundColor: buttonBgColor,
            color: "white",
            padding: "16px 32px",
            borderRadius: 12,
            fontSize: width * 0.015,
            fontWeight: 600,
            transform: `scale(${finalButtonScale})`,
            opacity: buttonOpacity,
            boxShadow: "0 4px 12px rgba(0,0,0,0.05)",
            transformOrigin: "center",
            transition: "none",
          }}
        >
          {buttonText}
        </div>

        {/* Loading Spinner */}
        <div
          style={{
            position: "absolute",
            left: "60px",
            top: "14px",
            opacity: loadingOpacity,
            transform: `rotate(${loadingRotation}deg)`,
            transformOrigin: "center",
            transition: "none",
          }}
        >
          <svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke={completedButtonColor} strokeWidth="3" strokeLinecap="round">
            <circle cx="12" cy="12" r="10" strokeOpacity="0.2" />
            <path d="M12 2 a10 10 0 0 1 10 10" />
          </svg>
        </div>

        {/* Verified Badge and Text */}
        <div
          style={{
            position: "absolute",
            display: "flex",
            alignItems: "center",
            gap: "12px",
            transform: `scale(${badgeScale})`,
            opacity: badgeScale > 0 ? 1 : 0,
            transformOrigin: "left center",
            transition: "none",
            paddingTop: "14px", // Align vertically somewhat with where button text was
          }}
        >
          <svg width="32" height="32" viewBox="0 0 24 24" fill="none">
            <path d="M12 1L3 5v6c0 5.55 3.84 10.74 9 12 5.16-1.26 9-6.45 9-12V5l-9-4z" fill={verifiedBadgeColor} />
            <path d="M10 16.5l-4-4 1.41-1.41L10 13.67l6.59-6.59L18 8.5l-8 8z" fill="#ffffff" />
          </svg>
          <span style={{
            fontSize: width * 0.014,
            color: verifiedTextColor,
            fontWeight: 400,
          }}>
            {verifiedText}
          </span>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default ClientContractAnimation;